css:
.tpl-navy-gold *{box-sizing:border-box;margin:0;padding:0;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.tpl-navy-gold,.tpl-navy-gold{width:210mm;height:297mm}
.tpl-navy-gold{font-family:Poppins,sans-serif;color:#17336B}
.tpl-navy-gold .page{position:relative;width:210mm;height:297mm;overflow:hidden;background:#fff}
.tpl-navy-gold .hdr{position:absolute;left:12mm;top:5mm;display:flex;align-items:center;gap:3mm}
.tpl-navy-gold .crest{width:11mm;height:11mm;border-radius:50%;background:#17336B;box-shadow:inset 0 0 0 .5mm #E8A823;display:flex;align-items:center;justify-content:center;color:#E8A823;font-size:12pt}
.tpl-navy-gold .hdr b{display:block;font:700 14pt/1.1 Poppins} .tpl-navy-gold .hdr small{font:500 7pt Poppins;letter-spacing:.2em;color:#B97A00}
.tpl-navy-gold .dots{position:absolute;right:50mm;top:6mm;display:grid;grid-template-columns:repeat(5,1.5mm);gap:2.2mm} .tpl-navy-gold .dots i{width:1.5mm;height:1.5mm;border-radius:50%;background:#7FB0EC}
.tpl-navy-gold .sun{position:absolute;right:-12mm;top:-14mm;width:36mm;height:36mm;border-radius:50%;background:#E8A823}
.tpl-navy-gold .ring{position:absolute;right:-26mm;top:-26mm;width:64mm;height:64mm;border-radius:50%;border:.4mm solid #17336B}
.tpl-navy-gold .hero{position:absolute;left:0;top:19mm;width:210mm;height:100mm}
.tpl-navy-gold .hero svg{width:100%;height:100%;display:block}
.tpl-navy-gold .hc{position:absolute;left:0;right:0;top:23mm;display:flex;flex-direction:column;align-items:center}
.tpl-navy-gold .pill{background:#fff;color:#17336B;font:700 8.6pt Poppins;letter-spacing:.1em;padding:2mm 9mm 2mm 12mm;border-radius:5mm;position:relative}
.tpl-navy-gold .pill:before{content:"";position:absolute;left:5mm;top:50%;width:1.6mm;height:1.6mm;margin-top:-.8mm;border-radius:50%;background:#E8A823}
.tpl-navy-gold .kick{margin-top:3mm;font:700 13pt Poppins;letter-spacing:.35em;color:#E8A823;padding-left:.35em}
.tpl-navy-gold .tri{font:700 56pt/1.05 Poppins;color:#fff;letter-spacing:.02em}
.tpl-navy-gold .ded{margin-top:2.5mm;border:.4mm solid #fff;color:#fff;font:700 8.4pt Poppins;letter-spacing:.14em;padding:1.8mm 9mm;border-radius:5mm}
.tpl-navy-gold .photo{position:absolute;left:50%;top:73mm;width:54mm;height:54mm;margin-left:-27mm;border-radius:50%;background:#E8A823;padding:1.9mm;box-shadow:0 1mm 3mm rgba(23,51,107,.35)}
.tpl-navy-gold .pw{width:100%;height:100%;border-radius:50%;background:#fff;padding:1.2mm}
.tpl-navy-gold .ph{position:relative;width:100%;height:100%;border-radius:50%;overflow:hidden;background:radial-gradient(circle at 50% 30%,#EAF2FC,#C9DCF5);display:flex;justify-content:center;align-items:flex-end}
.tpl-navy-gold .ph svg{width:80%;height:80%} .tpl-navy-gold .ph span{position:absolute;bottom:4mm;font:700 4.8pt Poppins;letter-spacing:.18em;color:#17336B}
.tpl-navy-gold .ph img.pimg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.tpl-navy-gold .rest{position:absolute;left:0;right:0;top:130mm;display:flex;flex-direction:column;align-items:center}
.tpl-navy-gold .name{font:700 24pt/1.15 Poppins;color:#17336B;letter-spacing:.01em}
.tpl-navy-gold .bar{width:18mm;height:1.2mm;border-radius:1mm;background:#E8A823;margin-top:1mm}
.tpl-navy-gold .role{margin-top:2.4mm;background:linear-gradient(90deg,#14A39A,#1E73D8);color:#fff;font:700 9pt Poppins;letter-spacing:.12em;padding:1mm 7mm;border-radius:4mm}
.tpl-navy-gold .tag{margin-top:2.2mm;font:700 7.6pt Poppins;letter-spacing:.24em;color:#14A39A}
.tpl-navy-gold .hh{margin-top:3mm;font:700 14pt Poppins;color:#17336B;display:flex;align-items:center;gap:2.5mm} .tpl-navy-gold .hh:before{content:"";width:2.4mm;height:2.4mm;border-radius:50%;background:#E8A823}
.tpl-navy-gold .card{margin-top:1.6mm;width:168mm;background:#EAF2FC;border-radius:4mm;padding:4mm 7mm;display:grid;grid-template-columns:1fr 1fr;gap:9mm;position:relative}
.tpl-navy-gold .card:before{content:"";position:absolute;left:3.4mm;top:5mm;bottom:5mm;width:1mm;border-radius:1mm;background:#E8A823}
.tpl-navy-gold .card:after{content:"";position:absolute;left:50%;top:5mm;bottom:5mm;width:.25mm;background:#C9DCF5}
.tpl-navy-gold .card p{font:400 7.7pt/1.42 Poppins;color:#2D4A80;margin-bottom:1.6mm} .tpl-navy-gold .card p.lead{font-weight:500;color:#17336B}
.tpl-navy-gold .end{margin-top:1mm;background:#17336B;border-radius:2.6mm;padding:2.4mm 4mm 2.4mm 9mm;position:relative;color:#fff;font:500 8pt/1.35 Poppins}
.tpl-navy-gold .end:before{content:"★";position:absolute;left:3mm;top:50%;transform:translateY(-50%);color:#E8A823;font-size:10pt} .tpl-navy-gold .end b{color:#E8A823;font-weight:500}
.tpl-navy-gold .foot{position:absolute;left:0;right:0;bottom:0;height:57mm;background:#17336B;border-top:1.4mm solid #E8A823;display:flex;flex-direction:column;align-items:center;padding-top:3.2mm;color:#fff}
.tpl-navy-gold .fl{font:500 7pt Poppins;letter-spacing:.18em;color:#7FB0EC} .tpl-navy-gold .ft{margin-top:1mm;font:500 6pt Poppins;letter-spacing:.3em}
.tpl-navy-gold .cv{font:700 28pt/1.1 Poppins;letter-spacing:.1em;color:#E8A823} .tpl-navy-gold .cy{font:700 6.6pt Poppins;letter-spacing:.18em}
.tpl-navy-gold .og{margin-top:1.8mm;font:700 5.6pt Poppins;letter-spacing:.35em;color:#7FB0EC}
.tpl-navy-gold .chips{display:flex;gap:1.4mm;margin-top:1.2mm} .tpl-navy-gold .chip{font:700 6.4pt Poppins;padding:1mm 3mm;border-radius:4mm}
.tpl-navy-gold .q{margin-top:1.8mm;font:italic 500 7pt Lora,serif} .tpl-navy-gold .u{position:absolute;bottom:1.6mm;font:700 5.8pt Poppins;letter-spacing:.3em;color:#E8A823}
